mapper.update:
UPDATE GYE_MEMBER
SET WARNING_COUNT = WARNING_COUNT + 1
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{targetMemberId}
AND STATUS = 'ACTIVE'
AND WARNING_COUNT < 2

mapper.select:
SELECT COUNT(*)
FROM WITHDRAWAL_REQUEST
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{targetMemberId}
AND STATUS IN ('SETTLEMENT_PENDING', 'CONSENT_PENDING')
